    for row, sup in enumerate(sets):
        F[row, list(sup)] = 1
    return F
def _valid(E, S, F):
    E = np.asarray(E)
    r = S.shape[0]
    if E.ndim != 2 or E.shape[1] != 2 or E.shape[0] == 0: return 0
    rows = [tuple(int(v) for v in e) for e in E.tolist()]
    if rows != sorted(set(rows)): return 0
    edges = set(rows)
    if any(a == b or not (0 <= a < r and 0 <= b < r) for a, b in edges): return 0
