        stack = [(s, (s,))]
        while stack:
            node, path = stack.pop()
            for nxt in succ[node]:
                if nxt == s: found.add(frozenset(path))
                elif nxt > s and nxt not in path: stack.append((nxt, path + (nxt,)))
    target = {frozenset(np.flatnonzero(row).tolist()) for row in F}
    return int(found == target)
